from pathlib import Path
import re

def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'{label}: anchor missing')
    return text.replace(old, new, 1)

# Reservation owner: establish package identity before the one canonical commit.
p=Path('workflow-engine.js'); text=p.read_text()
pattern=r"function reserve\(p,o=\{\}\)\{.*?\nfunction transitionReservation"
replacement=r'''function reserve(p,o={}){ensure(p);const n=Number(o.stage==null?p.activeStage:o.stage),operation=String(o.operation||'COMPLETE'),baseScope={...(o.scope||scope(p))},targetSlot=reservationTargetSlot(p,{stage:n,operation,scope:baseScope});if(o.targetSlot!=null&&String(o.targetSlot)!==targetSlot)throw new Error('TARGET_SLOT is application-calculated and cannot be supplied or overridden.');const ph=h.sha256Value(o.payload||{}),key=h.sha256Value({commandType:'RESERVE_OPERATION',contractProfileId:String(p.job?.CONTRACT_PROFILE_ID||schema.CONTRACT_PROFILE_ID||''),jobId:String(p.job?.JOB_ID||''),stage:n,operation,targetSlot,scope:Object.fromEntries(Object.entries(baseScope).filter(([scopeKey])=>scopeKey!=='projectRevision')),payloadHash:ph});const matching=safe(p?.projectData?.operationReservations).filter(r=>Number(fv(r,'STAGE'))===n&&String(fv(r,'OPERATION'))===operation&&String(fv(r,'TARGET_SLOT'))===targetSlot);const exact=matching.find(r=>String(fv(r,'IDEMPOTENCY_KEY'))===key);if(exact)return exact;if(matching.some(r=>RESERVATION_PRESERVING_STATES.has(up(fv(r,'STATUS')))))throw new Error('An authoritative reservation already controls this target operation slot.');const rev=Number(p.revision||0),reservationRevision=rev+1,reservationScope={...baseScope,projectRevision:reservationRevision},challengeNonce=nonce(),created=put(p,'operationReservations',{JOB_ID:String(p.job?.JOB_ID||''),STAGE:n,OPERATION:operation,TARGET_SLOT:targetSlot,PACKAGE_ID:'PENDING',PROMPT_ID:String(o.promptId||''),SCOPE:reservationScope,EXPECTED_REVISION:reservationRevision,RESERVATION_REVISION:reservationRevision,CHALLENGE_NONCE:challengeNonce,STATUS:'RESERVED',OWNING_TAB_INSTANCE:String(o.owningTabInstance||'UNKNOWN'),IDEMPOTENCY_KEY:key,PAYLOAD_HASH:ph},{stage:n,source:'APPLICATION_RESERVATION',scope:reservationScope}),operationReservationId=rid(created,'operationReservations'),packageId=`PACKAGE-${h.sha256Value({contractProfileId:String(p.job?.CONTRACT_PROFILE_ID||schema.CONTRACT_PROFILE_ID||''),jobId:String(p.job?.JOB_ID||''),stage:n,operation,targetSlot,operationReservationId,challengeNonce,promptId:String(o.promptId||''),reservationRevision}).slice(0,40).toUpperCase()}`;set(created,'operationReservations','PACKAGE_ID',packageId);p.revision=reservationRevision;return created;}
function transitionReservation'''
text,count=re.subn(pattern,replacement,text,count=1,flags=re.S)
if count!=1: raise SystemExit('workflow-engine reserve replacement failed')
p.write_text(text)

